<?php require __DIR__.'/../includes/bootstrap.php'; require_client();
$q=db()->prepare('SELECT b.*,d.name AS drum_name FROM bookings b JOIN drums d ON d.id=b.drum_id WHERE b.user_id=? ORDER BY b.created_at DESC'); $q->execute([user()['id']]); $rows=$q->fetchAll();
page_header('My bookings'); ?><div class="toolbar"><p class="muted">View your requests and their approval status here.</p><a class="button" href="book.php">＋ Book a drum</a></div><?php if(!$rows):?><div class="empty"><div class="empty-icon">🥁</div><h2>No bookings yet</h2><p>When you request a session, it will appear here.</p><a class="button" href="book.php">Make your first booking</a></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Drum</th><th>Session</th><th>Duration</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><?=e($b['drum_name'])?></td><td><?=e(date('M j, Y g:i A',strtotime($b['start_at'])))?></td><td><?= (int)$b['duration_hours']?> hr(s)</td><td><?=money($b['total_price'])?></td><td><span class="<?=e(booking_status_class($b['status']))?>"><?=e($b['status'])?></span></td><td><a class="text-link" href="booking.php?id=<?=(int)$b['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php page_footer();
